// Everything the Explore screen can browse: the library plus daily verses that are not
// already in it. Daily verses use their reference as id (that is how they are saved).
export const LIBRARY = [
  ...VERSES,
  ...DAILY_VERSES.filter((d) => !VERSES.some((v) => v.ref === d.ref)).map((d) => ({ ...d, id: d.ref, category: d.category || [] })),
];

// The key a verse is saved under. Library verses are saved by id; a verse saved from the
// daily card is saved by its reference, so check that first.
export function favoriteKey(verse, favorites) {
  return favorites.has(verse.ref) ? verse.ref : verse.id;
}

// Stable, URL-safe key for a verse reference, e.g. "Psalm 23:1" -> "psalm-23-1".
export function verseSlug(ref) {
  return String(ref || "").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
}

// Looks a verse up by slug across both lists (first match wins). Returns { ref, text, label } or null.
export function findVerse(slug) {
  if (!slug) return null;
  const hit = [...VERSES, ...DAILY_VERSES].find((x) => verseSlug(x.ref) === slug);
  // label: the reference to show people (the NABRE verse number where it differs from ref).
  return hit ? { ref: hit.ref, text: hit.text, label: hit.displayRef || hit.ref } : null;
}
